media_types.script:
var p = JSON.parse(value);
if (!p.url || !p.token) { throw 'Nowlert URL and source-scoped token are required'; }
if (p.url.indexOf('https://') !== 0) { throw 'Use an HTTPS Nowlert callback'; }
var nseverity = parseInt(p.event_nseverity, 10);
var severities = ['information', 'information', 'warning', 'warning', 'critical', 'critical'];
var recovered = String(p.event_value) === '0';
var severity = severities[nseverity] || 'warning';
var request = new HttpRequest();
request.addHeader('Content-Type: application/json');
request.addHeader('Authorization: Bearer ' + p.token);
var envelope = {
    schema: 'nowlert.event.v1', source: 'zabbix', provider: 'Zabbix', category: 'monitoring',
    title: String(p.subject || 'Zabbix notification').substring(0, 256),
    message: String(p.message || 'Zabbix event notification').substring(0, 4000),
    severity: severity, status: recovered ? 'resolved' : 'firing', host: String(p.host_name || '').substring(0, 256),
    metadata: {event_id: String(p.event_id || ''), event_source: String(p.event_source || ''),
        trigger: String(p.event_name || '').substring(0, 1000), notification_type: recovered ? 'RECOVERY' : 'PROBLEM'}
};
request.post(p.url.replace(/\/+$/, '') + '/api/v2/events', JSON.stringify(envelope));
var status = request.getStatus();
if (status < 200 || status >= 300) { throw 'Nowlert rejected the event (HTTP ' + status + ')'; }
return JSON.stringify({accepted: true, http_status: status, lifecycle: envelope.status});

